(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiCodex=api;})(typeof window!=='undefined'?window:globalThis,function(){
 'use strict';
 function record(state,item){state.characterDiscoveries=Array.isArray(state.characterDiscoveries)?state.characterDiscoveries:[];if(!state.characterDiscoveries.includes(item.char))state.characterDiscoveries.push(item.char);}
 function initialize(state,database){const allowed=new Set(database.map(i=>i.char));state.characterDiscoveries=[...new Set((state.characterDiscoveries||[]).filter(c=>allowed.has(c)))];for(const char of state.specialDiscoveries||[])if(allowed.has(char))record(state,{char});for(const item of state.inventory||[])if(allowed.has(item.char))record(state,item);return state;}
 function validSave(state,database){const list=state.characterDiscoveries;if(list===undefined)return true;const allowed=new Set(database.map(i=>i.char));return Array.isArray(list)&&list.length<=database.length&&new Set(list).size===list.length&&list.every(c=>typeof c==='string'&&allowed.has(c));}
 function summary(state,database,getReadings){const found=new Set(state.characterDiscoveries||[]),tiers=[1,2,3,4].map(jis=>({jis,found:0,total:0})),secret={found:0,total:0};for(const item of database){const tier=tiers[item.jis-1],known=found.has(item.char);if(tier){tier.total++;if(known)tier.found++;}if(!getReadings(item.char).length){secret.total++;if(known)secret.found++;}}return{found:database.filter(i=>found.has(i.char)).length,total:database.length,tiers,secret};}
 function list(state,database,getReadings,{status='found',jis='all',query=''}={}){const found=new Set(state.characterDiscoveries||[]),elementChars=new Set((typeof module==='object'&&module.exports?require('./element-characters.js'):window.KanjiElementCharacters).catalogue.map(e=>e.char));query=String(query).trim();return database.filter(item=>{const known=found.has(item.char),secret=!getReadings(item.char).length;if(jis==='fish'&&!(typeof module==='object'&&module.exports?require('./fish-characters.js'):window.KanjiFishCharacters).has(item)||jis==='element'&&!elementChars.has(item.char)||jis==='secret'&&!secret||jis!=='fish'&&jis!=='element'&&jis!=='secret'&&jis!=='all'&&item.jis!==Number(jis))return false;if(status==='found'&&!known||status==='missing'&&known)return false;if(query&&(!known&&secret||!item.char.includes(query)))return false;return true;});}
 return{record,initialize,validSave,summary,list};
});
